* {
  box-sizing: border-box;
}

body {
  margin: 0;
  color: #172033;
  background: #f7f8fa;
  font-family: Arial, Helvetica, sans-serif;
}

.dashboard-page {
  width: min(100% - 2rem, 72rem);
  margin: 0 auto;
  padding: 2rem 0;
}

.dashboard-page h1 {
  margin: 0 0 1.5rem;
  font-size: 1.875rem;
}

.dashboard-content {
  display: grid;
  gap: 1.25rem;
}

.grid {
  display: grid;
}

.grid-cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.gap-4 {
  gap: 1rem;
}

.card,
.chart,
.invoices {
  min-width: 0;
  padding: 1.25rem;
  border: 1px solid #e3e7ee;
  border-radius: 0.75rem;
  background: #fff;
}

.card h2,
.chart h2,
.invoices h2 {
  margin: 0 0 0.75rem;
  font-size: 1rem;
}

.card p {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
}

.chart ul,
.invoices ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.chart li,
.invoices li {
  padding: 0.5rem 0;
  border-top: 1px solid #edf0f4;
}

.dashboard-skeleton .dashboard-card {
  min-height: 7.25rem;
}

.skeleton-bar {
  display: block;
  border-radius: 0.35rem;
  background: linear-gradient(90deg, #edf0f4 25%, #f6f7f9 50%, #edf0f4 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.5s ease-in-out infinite;
}

.skeleton-label {
  width: 45%;
  height: 0.9rem;
  margin-bottom: 1.25rem;
}

.skeleton-value {
  width: 65%;
  height: 1.5rem;
}

.skeleton-chart {
  display: flex;
  height: 12rem;
  align-items: end;
  justify-content: space-around;
  gap: 0.75rem;
  padding: 1rem 0 0;
  border-bottom: 1px solid #e3e7ee;
}

.skeleton-chart .skeleton-bar {
  width: 8%;
}

.skeleton-invoices {
  display: grid;
  gap: 0.75rem;
}

.skeleton-invoices .skeleton-bar {
  height: 1.25rem;
}

.skeleton-invoices .skeleton-bar:nth-child(2) {
  width: 82%;
}

.skeleton-invoices .skeleton-bar:nth-child(3) {
  width: 68%;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes skeleton-shimmer {
  to {
    background-position: -200% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-bar {
    animation: none;
  }
}

@media (max-width: 38rem) {
  .grid-cols-2 {
    grid-template-columns: 1fr;
  }
}

